	for (i = 0; i < length; i++) {

		char ch = characters[i];

		if (afterNewLine && ch == comment) {
			while (++i < length) {
				ch = characters[i];
				if (ch == '\r' || ch == '\n' || ch == normalizedNewLine) {
					break;
				}
			}
			continue;
		}

