                out.writeInt(timeZone);
            } else if (timeZone < -9) {
                out.write('-');
                out.writeInt(-timeZone);
            } else if (timeZone < 0) {
                out.write('-');
                out.write('0');
                out.writeInt(-timeZone);
            }
            out.write(':');
